#include "turbo_agent_legacy_knowledge_migration.h"
#include <stdio.h>
#include <string.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"legacy migration failed at %d: %s\n",__LINE__,#x);return 1;}}while(0)
static ta_legacy_migration_text_t t(const char*s){ta_legacy_migration_text_t v={(const unsigned char*)s,strlen(s)};return v;}
static ta_legacy_migration_document_t doc(const char*id,const char*uri,const char*hash){ta_legacy_migration_document_t d={0};d.id=t(id);d.uri=t(uri);d.kind=t("file");d.title=t(id);d.size=12;d.mtime=5;d.content_hash=t(hash);d.updated_at=9;return d;}
static ta_legacy_migration_chunk_t chunk(const char*id,const char*docid,int64_t ordinal,const char*text){ta_legacy_migration_chunk_t c={0};c.id=t(id);c.document_id=t(docid);c.ordinal=ordinal;c.text=t(text);return c;}
static int normal(void){ta_legacy_migration_document_t d=doc("/root/a.txt","/root/a.txt","0123456789abcdef");ta_legacy_migration_chunk_t c[2]={chunk("/root/a.txt#0","/root/a.txt",0,"hello "),chunk("/root/a.txt#1","/root/a.txt",1,"world")};ta_legacy_migration_plan_t p,p2;CHECK(ta_legacy_knowledge_plan_document(&d,c,2,&p)==TA_LEGACY_MIGRATION_OK);CHECK(p.chunk_count==2&&p.extracted_text_bytes==11&&p.legacy_hash_shape==TA_LEGACY_HASH_HEX64_SHAPE_UNVERIFIED);CHECK(p.revision_record.content_length==12&&p.revision_record.source_mtime_seconds==5&&p.revision_record.observed_at_seconds==9&&p.revision_record.digest_kind==TA_SOURCE_REVISION_DIGEST_UNVERIFIED_LEGACY&&p.revision_record.retention==TA_SOURCE_REVISION_CONTENT_UNAVAILABLE);d.uri=t("renamed://alias");CHECK(ta_legacy_knowledge_plan_document(&d,c,2,&p2)==TA_LEGACY_MIGRATION_OK);CHECK(p.source_id.size==p2.source_id.size&&!memcmp(p.source_id.data,p2.source_id.data,p.source_id.size));CHECK(p.revision_id.size==p2.revision_id.size&&!memcmp(p.revision_id.data,p2.revision_id.data,p.revision_id.size));d.updated_at=10;CHECK(ta_legacy_knowledge_plan_document(&d,c,2,&p2)==TA_LEGACY_MIGRATION_OK);CHECK(memcmp(p.revision_id.data,p2.revision_id.data,p.revision_id.size));return 0;}
static int empty_and_opaque(void){ta_legacy_migration_document_t d=doc("note","memory://note","caller-supplied-hash");d.size=0;ta_legacy_migration_chunk_t c=chunk("note#0","note",0,"");ta_legacy_migration_plan_t p;CHECK(ta_legacy_knowledge_plan_document(&d,&c,1,&p)==TA_LEGACY_MIGRATION_OK);CHECK(p.legacy_hash_shape==TA_LEGACY_HASH_OPAQUE_UNVERIFIED&&p.extracted_text_bytes==0&&p.chunk_count==1);return 0;}
static int malformed(void){ta_legacy_migration_document_t d=doc("a","a","0123456789abcdef");ta_legacy_migration_chunk_t c[2]={chunk("a#0","a",0,"x"),chunk("a#1","a",1,"y")};ta_legacy_migration_plan_t p;c[1].ordinal=2;CHECK(ta_legacy_knowledge_plan_document(&d,c,2,&p)==TA_LEGACY_MIGRATION_MALFORMED&&p.source_id.size==0);c[1].ordinal=1;c[1].document_id=t("b");CHECK(ta_legacy_knowledge_plan_document(&d,c,2,&p)==TA_LEGACY_MIGRATION_MALFORMED);c[1].document_id=t("a");c[1].id=t("a#01");CHECK(ta_legacy_knowledge_plan_document(&d,c,2,&p)==TA_LEGACY_MIGRATION_MALFORMED);c[1].id=t("a#1");CHECK(ta_legacy_knowledge_plan_document(&d,NULL,0,&p)==TA_LEGACY_MIGRATION_MALFORMED);return 0;}
static int long_id(void){static unsigned char id[250],cid[252];memset(id,'a',sizeof(id));memcpy(cid,id,sizeof(id));cid[250]='#';cid[251]='0';ta_legacy_migration_document_t d=doc("a","a","0123456789abcdef");d.id=(ta_legacy_migration_text_t){id,sizeof(id)};d.uri=d.id;ta_legacy_migration_chunk_t c={0};c.id=(ta_legacy_migration_text_t){cid,sizeof(cid)};c.document_id=d.id;c.ordinal=0;c.text=t("x");ta_legacy_migration_plan_t p;CHECK(ta_legacy_knowledge_plan_document(&d,&c,1,&p)==TA_LEGACY_MIGRATION_REINGEST_REQUIRED);CHECK(!p.source_id.size&&!p.revision_id.size);return 0;}
int main(void){if(normal()||empty_and_opaque()||malformed()||long_id())return 1;puts("TurboAgent legacy KnowledgeStore migration planner PASS");return 0;}
